CREATE OR REPLACE FUNCTION get_row_count(p_table_name TEXT, p_status TEXT)
RETURNS BIGINT AS $$
DECLARE
    v_count BIGINT;
BEGIN
    -- %I safely quotes SQL identifiers; $1 binds parameters
    EXECUTE format('SELECT count(*) FROM %I WHERE status = $1', p_table_name)
    INTO v_count
    USING p_status;

    RETURN v_count;
END;
$$ LANGUAGE plpgsql;
